import{z as i,x as B,o as E,c as d,q as o,j as A,D as t,d as l,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"TMAH 与显影液","description":"","frontmatter":{"title":"TMAH 与显影液","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/tmah-developer.md","filePath":"litho/tmah-developer.md","lastUpdated":1791063341000}'),p={name:"litho/tmah-developer.md"};function m(h,a,T,D,u,f){const r=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=o('<h1 id="tmah-与显影液" tabindex="-1">TMAH 与显影液 <a class="header-anchor" href="#tmah-与显影液" aria-label="Permalink to &quot;TMAH 与显影液&quot;">​</a></h1><div class="epigraph"><p>0.26 N TMAH 是正性 CAR 的工业默认碱；浓度、温度和表面活性剂改的是溶解阈值，不是空中像。</p><footer>—— 对照工业标准 tetramethylammonium hydroxide 显影液</footer></div><p><a href="/litho/develop-puddle">上一课</a>给出铺液方式。缺口是液体是什么：四甲基氢氧化铵（TMAH）水溶液，常标 2.38 wt%（约 0.26 N）。主干胶课假定「碱显影」；本课钉这一默认契约，以及为什么不能当纯水漂。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>正胶曝光区聚合物变亲水、可溶。碱浓度决定阈值：过稀，该溶的不溶；过浓，未曝光区也咬。温度几度就改速率，轨道显影模块的液温是 CDU 源。把显影液当成「水」，会把化学对比度派给 PEB。</p><p><span class="marginnote">TMAH 有毒性与废水约束，厂内是危险化学品管理对象。本课只写工艺角色，不写操作规程替代 MSDS。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>浓度、温度、表面活性剂（下一课冲洗也会用）写进配方。新鲜液对循环液：循环降低成本，但带溶解产物，阈值漂。过滤与补给是缺陷课的前置。负胶或金属氧化物胶可能不用 TMAH——本课不吞并。</p>',8)),(E(),A(s,null,{default:t(()=>[n(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TMAH%5B%220.26%20N%20TMAH%22%5D%20--%3E%20THR%5B%22%E6%BA%B6%E8%A7%A3%E9%98%88%E5%80%BC%22%5D%0A%20%20TEMP%5B%22%E6%B6%B2%E6%B8%A9%22%5D%20--%3E%20THR%0A%20%20THR%20--%3E%20CD%5B%22%E7%BA%BF%E5%AE%BD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><span class="marginnote">0.26 N 是当量浓度：每升溶液含 0.26 摩尔的碱当量。代个数——TMAH 摩尔质量约 91 g/mol，0.26 mol/L 就是约 23.7 g/L，折回质量分数正是 2.38 wt%。两套标号说的是同一瓶显影液。</span></p><p>酚羟基（或 CAR 脱保护后的羧酸）在碱中电离，聚合物链溶剂化后离开膜。离子强度改双电层与溶胀，从而改倒塌风险——后课倒塌抑制会回到液面张力，不全是 TMAH 浓度。</p><p><span class="marginnote">常见误区：把显影液当成「把胶洗掉的水」。实际上未曝光区必须在整个显影时间里纹丝不动地扛住碱液——对比度来自「该溶的溶、不该溶的一丝不溶」。浓度一漂，好的线变宽、坏的底被咬薄，两者一起发生。</span></p><p><span class="marginnote">为什么液温被盯得这么紧：显影是化学反应，速率随温度指数式变化，液温漂几度，同一片晶圆上的线宽就整体平移。轨道机把显影液温控在很窄的窗口内，是 CD 均匀性的第一道闸门。</span></p>',5)),(E(),A(s,null,{default:t(()=>[n(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20OH%5B%22OH-%20%E7%A6%BB%E5%AD%90%E8%BF%9B%E6%94%BB%22%5D%20--%3E%20EXP%5B%22%E6%9B%9D%E5%85%89%E5%8C%BA%3A%20%E7%BE%A7%E9%85%B8%E7%94%B5%E7%A6%BB%22%5D%0A%20%20OH%20--%3E%20UN%5B%22%E6%9C%AA%E6%9B%9D%E5%85%89%E5%8C%BA%3A%20%E4%BB%8D%E7%96%8F%E6%B0%B4%22%5D%0A%20%20EXP%20--%3E%20SOL%5B%22%E9%93%BE%E6%BA%B6%E5%89%82%E5%8C%96%E6%BA%B6%E5%87%BA%22%5D%0A%20%20UN%20--%3E%20KEEP%5B%22%E4%B8%8D%E6%BA%B6%E8%A7%A3%E7%95%99%E8%86%9C%22%5D%0A%20%20SOL%20--%3E%20POS%5B%22%E6%AD%A3%E6%80%A7%E5%9B%BE%E6%A1%88%3A%20%E7%BA%BF%E4%B8%8E%E5%AD%94%22%5D%0A%20%20KEEP%20--%3E%20POS%0A%20%20SOL%20--%3E%20SWELL%5B%22%E8%BF%87%E5%BA%A6%E6%BA%B6%E8%83%80%22%5D%0A%20%20SWELL%20--%3E%20COLL%5B%22%E7%BA%BF%E5%80%92%E5%A1%8C%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("h2",{id:"边界",tabindex:"-1"},[l("边界 "),e("a",{class:"header-anchor",href:"#边界","aria-label":'Permalink to "边界"'},"​")],-1)),a[5]||(a[5]=e("p",null,"不写有机溶剂显影或干法显影化学。下一课冲洗：把碱和产物带走，毛细力开始主导。",-1)),a[6]||(a[6]=e("h2",{id:"小结",tabindex:"-1"},[l("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[7]||(a[7]=e("ul",null,[e("li",null,"工业正胶默认 0.26 N TMAH；浓度与温度是 CD 旋钮。"),e("li",null,"循环污染会漂阈值。"),e("li",null,"出处：TMAH 显影工业通识；Mack 溶解语境。")],-1))])}const H=i(p,[["render",m]]);export{C as __pageData,H as default};
